// TIEN404 LIVE03D safe QA tool. NEVER touches external systems.
const raw = typeof query === 'string' ? query : String(query?.query ?? '');
const parsed = /^([A-Z][0-9]{3})\|([1-9][0-9]{0,2})$/.exec(raw.trim());
if (!parsed) return JSON.stringify({status:'DENIED',code:'INVALID_CATALOG_QUERY',mockOnly:true,writes:0});
const [,sku,qtyStr] = parsed;
const qty=Number(qtyStr);
const products=Object.freeze({
 A002:{name:'Áo thun nam trắng basic size M',priceVnd:159000,stock:25},
 A004:{name:'Áo polo nam xanh navy size M',priceVnd:289000,stock:14}
});
if(!Object.hasOwn(products,sku))return JSON.stringify({status:'DENIED',code:'SKU_NOT_IN_SHOP_QA_A',mockOnly:true,writes:0});
const p=products[sku], total=p.priceVnd*qty;
return JSON.stringify({status:'SYNTHETIC_QUOTE_ONLY',shop:'SHOP_QA_A',sku,
 name:p.name,quantity:qty,unitPriceVnd:p.priceVnd,totalVnd:total,
 stockSnapshot:p.stock,mockOnly:true,externalWrites:0,actualOrder:false,
 note:'Dữ liệu QA tổng hợp. Không phải giá/tồn kho Commerce thật.'});

// TIEN404 LIVE03D QA tool. HARD no write, no external systems, no side-effect API.
const raw=typeof query==='string'?query:String(query?.query??'');
const s=raw.trim().toUpperCase();
if(s.startsWith('CONFIRM|')||s.startsWith('APPLY|')||s.startsWith('SAVE|')
  ||s.startsWith('CANCEL|')||s.startsWith('MANAGE|')){
 return JSON.stringify({status:'CONFIRM_BLOCKED_NO_TRUSTED_META_CONTEXT',
  mockOnly:true,realOrder:false,externalWrites:0,providerSends:0,
  message:'Preview không có HMAC người gửi được xác minh. Không xác nhận, không lưu đơn.'});
}
const m=/^PREPARE\|([A-Z][0-9]{3})\|([1-9][0-9]{0,2})\|([0-9]{1,12})$/.exec(s);
if(!m)return JSON.stringify({status:'DENIED',code:'INVALID_DRYRUN_INPUT',externalWrites:0,mockOnly:true});
const [,sku,quantityStr,totalStr]=m, quantity=Number(quantityStr),
 claimedTotal=Number(totalStr);
const fixture=Object.freeze({A002:{priceVnd:159000,stock:25},A004:{priceVnd:289000,stock:14}});
if(!Object.hasOwn(fixture,sku))return JSON.stringify({status:'DENIED',code:'QA_SKU_UNAVAILABLE',externalWrites:0,mockOnly:true});
const row=fixture[sku],actualTotal=row.priceVnd*quantity;
if(quantity>row.stock)return JSON.stringify({status:'DENIED',code:'QA_STOCK_INSUFFICIENT',externalWrites:0,mockOnly:true});
if(!Number.isSafeInteger(claimedTotal)||claimedTotal!==actualTotal)return JSON.stringify({status:'DENIED',code:'EXPECTED_TOTAL_MISMATCH',expectedTotalVnd:actualTotal,externalWrites:0,mockOnly:true});
return JSON.stringify({status:'AWAITING_CONFIRMATION_DRYRUN',store:'SHOP_QA_A',sku,quantity,
 totalVnd:actualTotal,reference:'QA-NOT-SAVED-'+sku+'-'+quantity,
 mockOnly:true,realOrder:false,externalWrites:0,stockReserved:false,
 providerSends:0,message:'Mã minh họa, không có đơn lưu trong hệ thống.'});

